RCT_EXPORT_METHOD(startVideoStream:(RCTPromiseResolveBlock)resolve
                  reject:(RCTPromiseRejectBlock)reject)
{
  // TODO: Replace mock
  _isStreaming = YES;
  dispatch_queue_t queue = dispatch_get_global_queue(DISPATCH_QUEUE_PRIORITY_DEFAULT, 0);
  _videoTimer = dispatch_source_create(DISPATCH_SOURCE_TYPE_TIMER, 0, 0, queue);
  dispatch_source_set_timer(_videoTimer, dispatch_time(DISPATCH_TIME_NOW, 0), 2 * NSEC_PER_SEC, 0);
  dispatch_source_set_event_handler(_videoTimer, ^{
    if (self.isStreaming) {
      [self sendEventWithName:@"onVideoFrame" body:@{
        @"base64": @"/9j/4AAQSkZJRgABAQEASABIAAD/mockframe",
        @"width": @(1280),
        @"height": @(720),
        @"timestamp": @([[NSDate date] timeIntervalSince1970] * 1000)
      }];
    }
  });
  dispatch_resume(_videoTimer);
  resolve(nil);
}

RCT_EXPORT_METHOD(stopVideoStream:(RCTPromiseResolveBlock)resolve
                  reject:(RCTPromiseRejectBlock)reject)
{
  _isStreaming = NO;
  if (_videoTimer) {
    dispatch_source_cancel(_videoTimer);
    _videoTimer = nil;
  }
  resolve(nil);
}

RCT_EXPORT_METHOD(speakText:(NSString *)text
                  resolve:(RCTPromiseResolveBlock)resolve
                  reject:(RCTPromiseRejectBlock)reject)
{
  dispatch_async(dispatch_get_main_queue(), ^{
    AVSpeechUtterance *utterance = [AVSpeechUtterance speechUtteranceWithString:text];
    utterance.voice = [AVSpeechSynthesisVoice voiceWithLanguage:@"es-MX"];
    utterance.rate = 0.5;
    [self.synthesizer speakUtterance:utterance];
    resolve(nil);
  });
}

